var a=[{name:"Dr n. med. Rafa\u0142 Drozda",title:"Specjalista chirurgii og\xF3lnej i onkologicznej. Specjalista gastroenterolog, proktolog.",bio:"Jest specjalist\u0105 chirurgii og\xF3lnej i onkologicznej, kt\xF3ry od lat zajmuje si\u0119 przede wszystkim leczeniem chor\xF3b przewodu pokarmowego i proktologi\u0105.",photo:"images/zespol/rafal-drozda.webp",znanyLekarz:"https://www.znanylekarz.pl/rafal-drozda/chirurg-onkologiczny-proktolog-gastrolog/lodz"},{name:"lek. Magdalena Bara\u0144ska",title:"Gastroenterolog",bio:"Swoje zainteresowania zawodowe skupia wok\xF3\u0142 diagnostyki i leczenia g\u0142\xF3wnie nieswoistych chor\xF3b zapalnych jelit (wrzodziej\u0105ce zapalenie jelita grubego, choroba Le\u015Bniowskiego - Crohna), jak r\xF3wnie\u017C ostrego i przewlek\u0142ego zapalenia trzustki.",photo:"images/zespol/magdalena-baranska.webp",znanyLekarz:"https://www.znanylekarz.pl/magdalena-baranska/gastrolog-internista/lodz"},{name:"lek. Karolina Kabot",title:"Anestezjolog"},{name:"lek. Leszek Weber",title:"Anestezjolog"},{name:"Dr n.med. Jacek Przyby\u0142a",title:"Lekarz specjalista w zakresie urologii",bio:"Studia medyczne uko\u0144czy\u0142 jako absolwent Wydzia\u0142u Lekarskiego Akademii Medycznej w \u0141odzi, w 2008 roku uzyska\u0142 tytu\u0142 specjalisty europejskiego w dziedzinie urologii."},{name:"Dr n.med. Krzysztof Grzegorczyk",title:"Specjalista w zakresie medycyny internistycznej, gastroenterologii oraz chor\xF3b zaka\u017Anych",bio:"Studia medyczne uko\u0144czy\u0142 jako absolwent Wojskowej Akademii Medycznej w \u0141odzi, a w roku 1986 uzyska\u0142 stopie\u0144 doktora nauk medycznych.",znanyLekarz:"https://www.znanylekarz.pl/krzysztof-grzegorczyk/gastrolog/lodz"},{name:"Dr Karolina Niczyporuk",title:"Lekarz specjalista w zakresie otolaryngologii dzieci\u0119cej",bio:"Uko\u0144czy\u0142a studia medyczne na Wydziale Wojskowo - Lekarskim Uniwersytetu Medycznego w \u0141odzi. Aktualnie zajmuje stanowisko M\u0142odszego Asystenta w Klinice Otolaryngologii Audiologii i Foniatrii Dzieci\u0119cej.",photo:"images/zespol/karolina-niczyporuk.webp"},{name:"lek. Julia Banasik",title:"Gastroenterolog",bio:"W swojej pracy klinicznej zajmuje si\u0119 diagnostyk\u0105 i leczeniem chor\xF3b przewodu pokarmowego, a jej szczeg\xF3lnym obszarem zainteresowania s\u0105 nieswoiste choroby zapalne jelit oraz choroba uchy\u0142kowa.",photo:"images/zespol/julia-banasik.webp",znanyLekarz:"https://www.znanylekarz.pl/julia-banasik/gastrolog/lodz"},{name:"Prof. dr hab. n.med. Joanna Jerzy\u0144ska",title:"Lekarz specjalista w zakresie pediatrii oraz alergologii",bio:"Studia medyczne uko\u0144czy\u0142a na Akademii Medycznej w \u0141odzi, w 2001 r. zdoby\u0142a tytu\u0142 specjalisty w dziedzinie pediatrii (I st.) jak r\xF3wnie\u017C tytu\u0142 doktora nauk medycznych.",photo:"images/zespol/joanna-jerzynska.webp"},{name:"lek. \u0141ukasz Spadli\u0144ski",title:"Kardiolog",bio:"Jest specjalist\u0105 kardiologii. Od 2019 roku pracuje w Klinice Kardiologii CSK UM w \u0141odzi, gdzie na co dzie\u0144 zajmuje si\u0119 diagnostyk\u0105 oraz leczeniem chor\xF3b serca.",photo:"images/zespol/lukasz-spadlinski-kardiolog.webp",znanyLekarz:"https://www.znanylekarz.pl/lukasz-spadlinski/kardiolog/lodz"},{name:"Dominika Buczy\u0144ska",title:"Psycholog",bio:"Pracuje z dzie\u0107mi, m\u0142odzie\u017C\u0105 i doros\u0142ymi. Specjalizuje si\u0119 w pracy z ma\u0142ymi dzie\u0107mi w zakresie wczesnego wspomagania rozwoju."},{name:"Dr n.med. Natalia Zawada-Kornalewicz",title:"Lekarz specjalista w zakresie chor\xF3b wewn\u0119trznych, diabetologii i endokrynologii",bio:"Uko\u0144czy\u0142a studia medyczne jako absolwent Uniwersytetu Medycznego w \u0141odzi, a nast\u0119pnie uzyska\u0142a tytu\u0142 doktora nauk medycznych.",photo:"images/zespol/natalia-zawada-kornalewicz.webp"},{name:"dr n. med. Hubert Zatorski",title:"Gastroenterolog",bio:"Cz\u0142onek towarzystw naukowych: Polskiego Towarzystwa Gastroenterologicznego, European Society of Gastrointestinal Endoscopy (ESGE), Polskiego Towarzystwa \u017Bywienia Pozajelitowego, Dojelitowego i Metabolizmu (POLSPEN).",znanyLekarz:"https://www.znanylekarz.pl/hubert-zatorski/gastrolog/lodz"},{name:"Dr n.med. Agnieszka Ba\u0142a",title:"Lekarz specjalista w zakresie medycyny internistycznej oraz farmakologii klinicznej",bio:"Uko\u0144czy\u0142a studia medyczne jako absolwentka Wydzia\u0142u Lekarskiego Akademii Medycznej w \u0141odzi, posiada r\xF3wnie\u017C tytu\u0142 doktora nauk medycznych.",photo:"images/zespol/agnieszka-bala.webp",znanyLekarz:"https://www.znanylekarz.pl/agnieszka-bala-2/internista/lodz"},{name:"Dr n.med. Dorota Czech",title:"Lekarz specjalista w zakresie otolaryngologii - w szczeg\xF3lno\u015Bci dzieci\u0119cej",bio:"Studia medyczne uko\u0144czy\u0142a jako absolwentka Wydzia\u0142u Lekarskiego Uniwersytetu Medycznego w \u0141odzi, a nast\u0119pnie kontynuowa\u0142a swoj\u0105 \u015Bcie\u017Ck\u0119 edukacji na studiach doktoranckich UM w \u0141odzi."},{name:"Dr n.med. \u0141ukasz Przys\u0142o",title:"Specjalista w dziedzinie epileptologii, neurologii dzieci\u0119cej i pediatrii",bio:"Studia medyczne uko\u0144czy\u0142 na Uniwersytecie Medycznym w \u0141odzi, a kilka lat p\xF3\u017Aniej zdoby\u0142 stopie\u0144 doktora nauk medycznych (2009 r.)."},{name:"Dr Joanna Kowalska-Majka",title:"Lekarz specjalista w zakresie reumatologii oraz chor\xF3b wewn\u0119trznych",bio:"Studia medyczne uko\u0144czy\u0142a jako absolwentka Wydzia\u0142u Lekarskiego Uniwersytetu Medycznego w \u0141odzi.",photo:"images/zespol/joanna-kowalska-majka.webp",znanyLekarz:"https://www.znanylekarz.pl/joanna-kowalska-majka/reumatolog-internista/lodz"},{name:"lek. Micha\u0142 Stasiak",title:"Gastroenterolog",bio:"Obszar zainteresowa\u0144 w toku pracy zawodowej dotyczy chor\xF3b zapalnych trzustki (ostrego i przewlek\u0142ego zapalenia trzustki) oraz raka tego narz\u0105du, jak r\xF3wnie\u017C nieswoistych chor\xF3b zapalnych jelit.",photo:"images/zespol/michal-stasiak.webp",znanyLekarz:"https://www.znanylekarz.pl/michal-stasiak/gastrolog-internista/rzgow"},{name:"dr n. med. Dariusz Krzyczmanik",title:"Specjalista chor\xF3b zaka\u017Anych",bio:"Specjalista chor\xF3b wewn\u0119trznych oraz chor\xF3b zaka\u017Anych z wieloletnim do\u015Bwiadczeniem klinicznym. Zajmuje si\u0119 diagnostyk\u0105 i leczeniem schorze\u0144 internistycznych oraz zaka\u017Anych u pacjent\xF3w doros\u0142ych i dzieci.",photo:"images/zespol/dariusz-krzyczmanik.webp",znanyLekarz:"https://www.znanylekarz.pl/dariusz-krzyczmanik/internista-lekarz-chorob-zakaznych/lodz"},{name:"dr n. med. Milena Padysz",title:"Gastroenterolog",bio:"Podczas pracy zajmuje si\u0119 rozpoznawaniem i leczeniem chor\xF3b przewodu pokarmowego, zw\u0142aszcza nieswoistych chor\xF3b zapalnych jelit, choroby uchy\u0142kowej jelita grubego oraz zaburze\u0144 czynno\u015Bciowych jelit.",photo:"images/zespol/milena-padysz.webp",znanyLekarz:"https://www.znanylekarz.pl/milena-padysz/gastrolog-internista/lodz"},{name:"dr n. med. i n. o zdr. Danuta Dom\u017Ca\u0142-Magrowska",title:"Lekarz specjalista gastroenterologii i chor\xF3b wewn\u0119trznych",bio:"Jest lekarzem specjalist\u0105 gastroenterologii i chor\xF3b wewn\u0119trznych. Z wyr\xF3\u017Cnieniem uko\u0144czy\u0142a wydzia\u0142 lekarski Uniwersytetu Medycznego.",photo:"images/zespol/danuta-domzal-magrowska.webp",znanyLekarz:"https://www.znanylekarz.pl/danuta-domzal-magrowska/gastrolog-internista/lodz"},{name:"Dr hab n. med. Mariola \u015Awiderek-Matysiak",title:"Specjalista w zakresie neurologii oraz lekarz medycyny",bio:"Jest absolwentk\u0105 Akademii Medycznej w \u0141odzi, kt\xF3r\u0105 uko\u0144czy\u0142a z wyr\xF3\u017Cnieniem. W 1998 r. rozpocz\u0119\u0142a studia doktoranckie na rodzimej uczelni."},{name:"Dr Katarzyna Przyby\u0142owska-Kustosik",title:"Lekarz specjalista w zakresie psychiatrii",bio:"Uko\u0144czy\u0142a studia medyczne na Wydziale Lekarskim Uniwersytetu Medycznego w Bia\u0142ymstoku. Uko\u0144czy\u0142a kurs psychoterapii w Instytucie Ericksonowskim w \u0141odzi.",photo:"images/zespol/dr-katarzyna-przybylowska-kustosik.webp"},{name:"Dr n. med. Izabela Kubi\u0144ska",title:"Specjalistka chor\xF3b dzieci\u0119cych i gastroenterologii",bio:"Uko\u0144czy\u0142a wydzia\u0142 lekarski na Uniwersytecie Medycznym w \u0141odzi, a specjalizacj\u0119 uzyska\u0142a w dziedzinie chor\xF3b dzieci\u0119cych i gastroenterologii, uzyskuj\u0105c ponadto stopie\u0144 naukowy doktora nauk medycznych.",photo:"images/zespol/izabela-kubinska.webp",znanyLekarz:"https://www.znanylekarz.pl/izabela-kubinska/pediatra-gastrolog/lodz"},{name:"Dr n. med. Aleksandra Ba\u0142a-Wojsznis",title:"Lekarz specjalista w zakresie dermatologii oraz wenerologii",bio:"Uko\u0144czy\u0142a studia medyczne na Wydziale Wojskowo - Lekarskim Akademii Medycznej w \u0141odzi. Posiada do\u015Bwiadczenie w prowadzeniu bada\u0144 klinicznych jako wsp\xF3\u0142badacz od 2008 roku.",photo:"images/zespol/aleksandra-bala-wojsznis-1.webp"},{name:"Dr n. med. Joanna Zboi\u0144ska",title:"Specjalistka chor\xF3b zaka\u017Anych, hepatolog",bio:"Zajmuje si\u0119 chorobami w\u0105troby i chorobami zaka\u017Anymi, wykonuje elastografi\u0119 w\u0105troby (FibroScan). Do\u015Bwiadczenie zdobywa\u0142a w renomowanych o\u015Brodkach europejskich, m.in. w Londynie.",znanyLekarz:"https://www.znanylekarz.pl/joanna-zboinska/hepatolog-lekarz-chorob-zakaznych/lodz"},{name:"lek. Natalia Wili\u0144ska-Spa\u0142ka",title:"Reumatolog",bio:"Zajmuje si\u0119 diagnostyk\u0105 i leczeniem zapalnych chor\xF3b staw\xF3w, chor\xF3b tkanki \u0142\u0105cznej, dny moczanowej i osteoporozy. Pracuje w Klinice Reumatologii WWCOiT im. M. Kopernika w \u0141odzi.",znanyLekarz:"https://www.znanylekarz.pl/natalia-wilinska-spalka/reumatolog/lodz"},{name:"lek. Kacper Mazur",title:"Lekarz rodzinny, lekarz pierwszego kontaktu",bio:"Prowadzi konsultacje z zakresu medycyny rodzinnej, medycyny podr\xF3\u017Cy i leczenia oty\u0142o\u015Bci. Uko\u0144czy\u0142 z wyr\xF3\u017Cnieniem Uniwersytet Medyczny w \u0141odzi oraz studia podyplomowe z medycyny podr\xF3\u017Cy i medycyny ekstremalnej na Uniwersytecie Jagiello\u0144skim.",znanyLekarz:"https://www.znanylekarz.pl/kacper-mazur-2/lekarz-rodzinny-lekarz-pierwszego-kontaktu/lodz"},{name:"lek. Klaudia Kubikowska-Mazur",title:"Dermatolog",bio:"Leczy ostre i przewlek\u0142e choroby sk\xF3ry u doros\u0142ych i dzieci - \u0142uszczyc\u0119, atopowe zapalenie sk\xF3ry, tr\u0105dzik, choroby w\u0142os\xF3w i paznokci. Specjalizacj\u0119 odbywa w Klinice Dermatologii, Dermatologii Dzieci\u0119cej i Onkologicznej szpitala im. Biega\u0144skiego w \u0141odzi.",znanyLekarz:"https://www.znanylekarz.pl/klaudia-kubikowska/dermatolog/lodz"},{name:"Dr n.med. Adam Rafa\u0142 Poliwczak",title:"Lekarz specjalista w zakresie kardiologii oraz chor\xF3b wewn\u0119trznych",bio:"Studia medyczne uko\u0144czy\u0142 na Wojskowej Akademii Medycznej w \u0141odzi, w 2003 r. uzyska\u0142 stopie\u0144 doktora nauk medycznych.",photo:"images/zespol/adam-poliwczak-kardiolog.webp",znanyLekarz:"https://www.znanylekarz.pl/adam-poliwczak/kardiolog-internista/lodz"}],e=[{name:"mgr Paulina Kruk",title:"Dietetyczka | Indywidualna dietoterapia i zmiana nawyk\xF3w \u017Cywieniowych",bio:"Dyplomowana dietetyczka z do\u015Bwiadczeniem w pracy z pacjentami, oferuj\u0105ca spersonalizowane podej\u015Bcie i praktyczne zalecenia \u017Cywieniowe."},{name:"Oliwia \u015Acigalska",title:"Dyplomowany dietetyk kliniczny",bio:"Dyplomowany dietetyk kliniczny, absolwentka Uniwersytetu Medycznego w \u0141odzi oraz autor artyku\u0142\xF3w dla Dietetycy.org.pl.",photo:"images/zespol/oliwia-scigalska.webp"}],i=[{name:"Adam Juszczak",title:"Dyrektor Zarz\u0105dzaj\u0105cy, W\u0142a\u015Bciciel i wsp\xF3\u0142tw\xF3rca AmiCare sp. z o.o. sp.k.",bio:"Absolwent Uniwersytetu Wroc\u0142awskiego. Od 2003 r. aktywnie dzia\u0142aj\u0105cy w bran\u017Cy medycznej. Otwarty na nowe wyzwania zar\xF3wno w AmiCare jak i w sporcie.",photo:"images/zespol/adam_juszczak.webp"},{name:"Micha\u0142 Bytomski",title:"Prezes Zarz\u0105du, W\u0142a\u015Bciciel i wsp\xF3\u0142tw\xF3rca AmiCare Centrum Medycznego",bio:"Absolwent Akademii Morskiej w Szczecinie. Wykwalifikowany specjalista od lat dzia\u0142aj\u0105cy w bran\u017Cy morskiej.",photo:"images/zespol/michal-bytomski.webp"},{name:"Marlena Serwaci\u0144ska",title:"Kierownik AmiCare Centrum Medycznego",bio:"Od 2015 roku pracuj\u0105ca w szpitalach jako piel\u0119gniarka, gdzie poznawa\u0142a potrzeby oraz problemy pacjent\xF3w.",photo:"images/zespol/marlena-serwacinska.webp"},{name:"Jakub Majka",title:"Kierownik Centrum Medycznego ds. us\u0142ug medycznych",bio:"Swoj\u0105 przygod\u0119 zawodow\u0105 rozpocz\u0105\u0142 w\u0142a\u015Bnie w AmiCare Centrum Medycznym.",photo:"images/zespol/jakub-majka.webp"},{name:"Anna G\xF3ra",title:"Kierownik o\u015Brodka bada\u0144 klinicznych",bio:"Absolwentka Uniwersytetu Medycznego w \u0141odzi. Od ponad 20 lat zwi\u0105zana z sektorem ochrony zdrowia.",photo:"images/zespol/anna-gora-sm.webp"}],o=[{name:"Maria Smul",title:"Koordynator bada\u0144 klinicznych",bio:"Z wykszta\u0142cenia - magister in\u017Cynier Biotechnologii, absolwentka Politechniki \u0141\xF3dzkiej. Posiada wieloletnie do\u015Bwiadczenie w badaniach klinicznych."},{name:"Dorota Sobczyk-C\u0142apa",title:"Koordynator bada\u0144 klinicznych",bio:"Uko\u0144czy\u0142a Uniwersytet \u0141\xF3dzki zdobywaj\u0105c tytu\u0142 magistra chemii, a tak\u017Ce Policealne Studium Farmaceutyczne pozwalaj\u0105ce na prac\u0119 w aptece jako technik farmaceutyczny.",photo:"images/zespol/dorota-sobczyk-clapa.webp"},{name:"Karolina Szcze\u015Bniak",title:"Koordynator bada\u0144 klinicznych",bio:"W 2011 roku rozpocz\u0119\u0142a swoj\u0105 przygod\u0119 w badaniach klinicznych przechodz\u0105c przez r\xF3\u017Cne stanowiska pracy.",photo:"images/zespol/karolina-szczesniak.webp"}],n=[{name:"Hubert Sadowski",title:"Piel\u0119gniarz",bio:"Piel\u0119gniarz z do\u015Bwiadczeniem zdobytym w warunkach Szpitalnego Oddzia\u0142u Ratunkowego.",photo:"images/zespol/hubert-sadowski-sm.webp"},{name:"Angelika Jurkiewicz",title:"Piel\u0119gniarka bada\u0144 klinicznych",bio:"Piel\u0119gniarka z do\u015Bwiadczeniem zdobytym w pracy z pacjentami pediatrycznymi.",photo:"images/zespol/amicare-angelika-jurkiewicz-sm.webp"},{name:"Dorota Dutkiewicz",title:"Piel\u0119gniarka"},{name:"Marta Galoch",title:"Piel\u0119gniarka"},{name:"Ma\u0142gorzata Pietrzykowska",title:"Piel\u0119gniarka"},{name:"Ewa Kaczmarek",title:"Piel\u0119gniarka"},{name:"Katarzyna Mirecka",title:"Piel\u0119gniarka"},{name:"Natalka Swiniarska",title:"Piel\u0119gniarka"},{name:"Damian Stefa\u0144ski",title:"Piel\u0119gniarz"},{name:"Damian Szczapa",title:"Piel\u0119gniarz"},{name:"Anna Hydzi\u0144ska",title:"Piel\u0119gniarka"},{name:"Bartek Depczy\u0144ski",title:"Piel\u0119gniarz"},{name:"Mateusz Szpunar",title:"Piel\u0119gniarz"},{name:"Jaros\u0142aw Pre\u015B",title:"Piel\u0119gniarz"},{name:"Bo\u017Cena Skrzydlak",title:"Piel\u0119gniarka"},{name:"Karolina Berkowska",title:"Ratownik Medyczny"},{name:"Micha\u0142 Tersa",title:"Ratownik Medyczny"},{name:"Wojciech Wolski",title:"Piel\u0119gniarz"}];export{a,e as b,i as c,o as d,n as e};
